"""Block reorder utilities for NPU Flex Attention.

Provides algorithms to reorder KV blocks accessed by each Q block row,
improving L2 cache locality and attention speed.
"""

import math
import torch
from dataclasses import dataclass
from typing import Optional, Tuple


def compute_and_set_pending_perm(kv_num_blocks: torch.Tensor, kv_indices: torch.Tensor,
                                  full_kv_num_blocks: Optional[torch.Tensor],
                                  full_kv_indices: Optional[torch.Tensor],
                                  mode: str = "wave_overlap",
                                  wave_size: int = 132,
                                  verbose: bool = False) -> Optional[torch.Tensor]:
    """Compute reorder permutation and set it via the flex_attention side channel.

    This is the main entry point for kernel-internal reorder.
    Call this BEFORE each flex_attention invocation that should use reorder.

    Args:
        kv_num_blocks, kv_indices: block mask sparse data
        full_kv_num_blocks, full_kv_indices: block mask full-block data
        mode: reorder algorithm (default "wave_overlap")
        wave_size: wave partition size
        verbose: print debug info

    Returns:
        perm tensor (1D int32 CPU, size=n_mask_blocks) or None if reorder
        would not help (identity permutation).
    """
    n_mask_blocks = kv_indices.shape[2]
    n_blocks_kv = kv_indices.shape[3]  # max KV blocks per Q block

    # Build dense mask on CPU
    mask_float = rebuild_block_mask(
        kv_num_blocks.cpu(), kv_indices.cpu(),
        n_mask_blocks, n_blocks_kv,
        full_kv_num_blocks=full_kv_num_blocks.cpu() if full_kv_num_blocks is not None else None,
        full_kv_indices=full_kv_indices.cpu() if full_kv_indices is not None else None,
        device="cpu",
    )

    # Run reorder algorithm
    if mode == "wave_overlap":
        perm_2d = wave_overlap_reorder(mask_float, wave_size=wave_size)  # (1, MB)
    elif callable(mode):
        perm_2d = mode(mask_float, wave_size=wave_size)
    else:
        raise ValueError(f"Unknown reorder mode: {mode}")

    perm = perm_2d[0].to(torch.int32)  # (MB,)

    # Skip if identity (no benefit)
    is_identity = torch.equal(perm, torch.arange(len(perm), dtype=torch.int32))
    if is_identity:
        if verbose:
            print("[reorder] Identity permutation — reorder skipped")
        return None

    # Set via side channel for the next flex_attention call
    from torch_npu._inductor.kernel.flex_attention import set_pending_perm
    set_pending_perm(perm.unsqueeze(0))

    if verbose:
        print(f"[reorder] Permutation set: {perm.tolist()}")

    return perm


def compute_block_hit_rate(kv_indices: torch.Tensor, kv_num_blocks: torch.Tensor,
                           full_kv_indices: Optional[torch.Tensor] = None,
                           full_kv_num_blocks: Optional[torch.Tensor] = None) -> float:
    """Compute the cache hit rate of KV block access pattern.

    A "hit" occurs when consecutive KV blocks accessed by a Q row
    are also consecutive in memory (index difference == 1).

    Args:
        kv_indices: Tensor[B, H, n_blocks, max_blocks] — per-row KV block indices
        kv_num_blocks: Tensor[B, H, n_blocks] — number of valid blocks per row
        full_kv_indices: optional full-block ranges
        full_kv_num_blocks: optional full-block range count

    Returns:
        float: hit rate in [0, 1]
    """
    B, H, n_blocks, max_blocks = kv_indices.shape
    total_transitions = 0
    total_hits = 0

    for b in range(B):
        for h in range(H):
            for row in range(n_blocks):
                # Collect all valid KV block indices (partial + full)
                all_indices = []

                # Partial blocks
                n_partial = int(kv_num_blocks[b, h, row].item())
                for i in range(n_partial):
                    all_indices.append(int(kv_indices[b, h, row, i].item()))

                # Fully-valid blocks: stored as individual indices (not ranges)
                if full_kv_num_blocks is not None and full_kv_indices is not None:
                    n_full = int(full_kv_num_blocks[b, h, row].item())
                    for i in range(n_full):
                        all_indices.append(int(full_kv_indices[b, h, row, i].item()))

                all_indices.sort()
                if len(all_indices) <= 1:
                    continue

                for i in range(len(all_indices) - 1):
                    total_transitions += 1
                    if all_indices[i + 1] - all_indices[i] == 1:
                        total_hits += 1

    if total_transitions == 0:
        return 0.0
    return total_hits / total_transitions


def rebuild_block_mask(kv_num_blocks: torch.Tensor, kv_indices: torch.Tensor,
                       n_blocks_q: int, n_blocks_kv: int,
                       full_kv_num_blocks: Optional[torch.Tensor] = None,
                       full_kv_indices: Optional[torch.Tensor] = None,
                       device=None) -> torch.Tensor:
    """Convert sparse block mask representation to dense mask.

    Correctly handles both partial blocks (kv_indices) and fully-valid
    block ranges (full_kv_indices).

    Args:
        kv_num_blocks: Tensor[B, H, n_blocks_q_mask] — partial block count per row
        kv_indices: Tensor[B, H, n_blocks_q_mask, max_blocks] — partial block indices
        n_blocks_q: int — target number of Q blocks for dense mask
        n_blocks_kv: int — target number of KV blocks for dense mask
        full_kv_num_blocks: optional Tensor[B, H, n_blocks_q_mask] — full-block range count
        full_kv_indices: optional Tensor[B, H, n_blocks_q_mask, max_pairs*2] — full-block ranges [start, end)
        device: optional device override

    Returns:
        mask_float: Tensor[B, n_blocks_q, n_blocks_kv] — 0/1 float mask
    """
    if device is None:
        device = kv_indices.device
    B, H, n_blocks_mask, max_blocks = kv_indices.shape
    mask = torch.zeros(B, n_blocks_q, n_blocks_kv, device=device, dtype=torch.float32)

    n_rows = min(n_blocks_q, n_blocks_mask)

    for b in range(B):
        # Use head 0 for mask shape (all heads share same mask for standard patterns)
        h = 0
        for row in range(n_rows):
            # 1) Partial blocks
            n_partial = int(kv_num_blocks[b, h, row].item())
            for i in range(n_partial):
                idx = int(kv_indices[b, h, row, i].item())
                if 0 <= idx < n_blocks_kv:
                    mask[b, row, idx] = 1.0

            # 2) Fully-valid blocks: stored as individual block indices
            if full_kv_num_blocks is not None and full_kv_indices is not None:
                n_full = int(full_kv_num_blocks[b, h, row].item())
                for i in range(n_full):
                    idx = int(full_kv_indices[b, h, row, i].item())
                    if 0 <= idx < n_blocks_kv:
                        mask[b, row, idx] = 1.0

    return mask


def fiedler_reorder(mask_float: torch.Tensor, wave_size: int = 132, n_iter: int = 20, trivial_mix: float = 0.0) -> torch.Tensor:
    """Normalized-Laplacian Fiedler vector + wave scheduling (production-quality).

    Ported from vllm-omni fiedler_wave_reorder / fiedler_mixed_nnz_reorder
    (greedy_reorder_cuda.py:2605, 2692, 2799).

    Key difference from simple SVD: uses D^{-1/2} W D^{-1/2} (cosine similarity
    between row access patterns) instead of raw M @ M^T (inner product). This
    eliminates NNZ bias — a dense row is NOT automatically "more similar".

    Pipeline:
      1. Compute degree deg[i] = sum_j (M_i @ M_j)
      2. Normalize adjacency: A = D^{-1/2} W D^{-1/2}
      3. Power iteration to find 2nd eigenvector (Fiedler) of A
      4. Deflate trivial eigenvector sqrt(deg) to remove degree leakage
      5. trivial_mix controls how much degree signal leaks into Fiedler
      6. Sort by Fiedler → wave partition → NNZ wave scheduling

    Args:
        mask_float: Tensor[..., MB, NB] float
        wave_size: rows per wave partition (default 132)
        n_iter: power iteration steps (default 20)
        trivial_mix: 0=pure Fiedler (no NNZ leak), 1=full degree correction

    Returns:
        perm: Tensor[..., MB] int64 permutation
    """
    *leading, MB, NB = mask_float.shape
    H = 1 if not leading else math.prod(leading)
    mask = mask_float.reshape(H, MB, NB)
    device = mask.device
    trivial_mix = min(1.0, max(0.0, float(trivial_mix)))

    nnz = mask.sum(dim=2)  # (H, MB)
    Mt = mask.transpose(1, 2)  # (H, NB, MB) cached

    # ── Step 1: Compute degree of row-similarity graph ──
    # deg[i] = sum_j W[i,j] = M[i,:] @ (M^T @ 1)
    ones = torch.ones(H, MB, 1, device=device)
    deg = torch.bmm(mask, torch.bmm(Mt, ones)).squeeze(2)  # (H, MB)
    dinv = 1.0 / deg.clamp(min=1e-8).sqrt()  # D^{-1/2}

    # ── Step 2: Trivial eigenvector for deflation ──
    # For normalized adjacency A = D^{-1/2} W D^{-1/2}, the trivial eigenvector
    # is sqrt(deg) (not all-ones). This is the correct deflation.
    # Use trivial_mix to blend: 0 = pure Fiedler, 1 = full NNZ leakage
    trivial_correct = deg.clamp(min=0.0).sqrt().unsqueeze(2)  # (H, MB, 1)
    trivial_correct = trivial_correct / trivial_correct.norm(dim=1, keepdim=True).clamp(min=1e-8)
    trivial_ones = torch.ones(H, MB, 1, device=device) / (MB ** 0.5)
    # blend: 0 = correct (pure Fiedler), 1 = all-ones (legacy SVD-like)
    trivial = (1.0 - trivial_mix) * trivial_correct + trivial_mix * trivial_ones
    trivial = trivial / trivial.norm(dim=1, keepdim=True).clamp(min=1e-8)

    # ── Step 3: Power iteration for Fiedler vector ──
    # Iterate v ← D^{-1/2} M (M^T (D^{-1/2} v)) — deflate — normalize
    gen = torch.Generator(device=device).manual_seed(42)
    v = torch.randn(H, MB, 1, device=device, generator=gen)
    v = v - torch.bmm(trivial.transpose(1, 2), v) * trivial
    v = v / v.norm(dim=1, keepdim=True).clamp(min=1e-8)

    for _ in range(n_iter):
        x = dinv.unsqueeze(2) * v                    # D^{-1/2} v
        y = torch.bmm(mask, torch.bmm(Mt, x))        # W @ (D^{-1/2} v)  [implicit, no S mat]
        v = dinv.unsqueeze(2) * y                    # D^{-1/2} W D^{-1/2} v
        v = v - torch.bmm(trivial.transpose(1, 2), v) * trivial  # deflate
        v = v / v.norm(dim=1, keepdim=True).clamp(min=1e-8)

    # ── Step 4: Sort by Fiedler projection ──
    # The Fiedler vector gives optimal 1D linear arrangement minimizing graph cut
    spectral_order = v[:, :, 0].argsort(dim=1)  # (H, MB)

    # ── Step 5: Wave scheduling (NNZ-based) ──
    n_waves = (MB + wave_size - 1) // wave_size
    pad = n_waves * wave_size - MB

    nnz_spectral = torch.gather(nnz, 1, spectral_order)

    if pad > 0:
        pad_idx = torch.arange(MB, MB + pad, device=device).unsqueeze(0).expand(H, -1)
        perm_padded = torch.cat([spectral_order, pad_idx], dim=1)
        nnz_padded = torch.cat([nnz_spectral, torch.zeros(H, pad, dtype=nnz.dtype, device=device)], dim=1)
    else:
        perm_padded = spectral_order
        nnz_padded = nnz_spectral

    # Reshape into waves
    nnz_waves = nnz_padded.view(H, n_waves, wave_size)  # (H, n_waves, wave_size)
    wave_mean_nnz = nnz_waves.float().mean(dim=2)  # (H, n_waves)

    # Dense waves first (latency hiding), NNZ descending within each wave
    wave_order = wave_mean_nnz.argsort(dim=1, descending=True)
    within_wave_order = nnz_waves.argsort(dim=2, descending=True)

    perm_waves = perm_padded.view(H, n_waves, wave_size)
    sorted_waves = torch.gather(perm_waves, 2, within_wave_order)

    wave_order_exp = wave_order.unsqueeze(2).expand(H, n_waves, wave_size)
    result_padded = torch.gather(sorted_waves, 1, wave_order_exp)

    # ── Step 6: Strip padding ──
    valid_mask = result_padded < MB
    result = result_padded[valid_mask].view(H, MB).contiguous()

    if leading:
        result = result.reshape(*leading, MB)
    return result


def wave_overlap_reorder(mask_float: torch.Tensor, wave_size: int = 132, n_iter: int = 10) -> torch.Tensor:
    """Wave-Overlap Reorder: 1D Spectral Sorting + Wave Scheduling.

    Ported from GPU vllm-omni (greedy_reorder_cuda.py:2441).

    Pipeline:
      1. Power iteration → top-1 left singular vector (Fiedler approx)
      2. Spectral sort: rows sorted by projection onto Fiedler vector (descending)
      3. Wave partition: chunk into wave_size groups
      4. Intra-wave NNZ sort: within each wave, sort by NNZ (descending, balances SM)
      5. Inter-wave schedule: reorder waves so dense waves run first (latency hiding)
      6. Strip padding

    Rows with similar KV access patterns are clustered together, improving L2
    cache locality and MSHR reuse.

    Args:
        mask_float: Tensor[..., MB, NB] — dense block mask (any leading dims)
        wave_size: int — wave partition size (default 132)
        n_iter: int — power iteration steps (default 10)

    Returns:
        perm: Tensor[..., MB] — row permutation indices
    """
    *leading, MB, NB = mask_float.shape
    H = 1 if not leading else math.prod(leading)
    mask_2d = mask_float.reshape(H, MB, NB)
    device = mask_float.device

    # ── Step 1: Power iteration for top-1 left singular vector ──
    gen = torch.Generator(device=device).manual_seed(42)
    V = torch.randn(H, NB, 1, device=device, generator=gen)

    for _ in range(n_iter):
        U = torch.bmm(mask_2d, V)  # (H, MB, 1)
        U = U / U.norm(dim=1, keepdim=True).clamp(min=1e-8)
        V = torch.bmm(mask_2d.transpose(1, 2), U)  # (H, NB, 1)
        V = V / V.norm(dim=1, keepdim=True).clamp(min=1e-8)

    # ── Step 2: Spectral sort (descending by Fiedler projection) ──
    proj = torch.bmm(mask_2d, V).squeeze(-1)  # (H, MB)
    spectral_order = proj.argsort(dim=1, descending=True)  # (H, MB)

    # ── Step 3: NNZ per row for wave scheduling ──
    nnz = mask_2d.sum(dim=2)  # (H, MB)
    n_waves = (MB + wave_size - 1) // wave_size

    # ── Step 4: Pad to multiple of wave_size ──
    pad = n_waves * wave_size - MB
    if pad > 0:
        pad_idx = torch.arange(MB, MB + pad, device=device).unsqueeze(0).expand(H, -1)
        spectral_order_pad = torch.cat([spectral_order, pad_idx], dim=1)
        nnz_pad = torch.cat([nnz, torch.zeros(H, pad, dtype=nnz.dtype, device=device)], dim=1)
    else:
        spectral_order_pad = spectral_order
        nnz_pad = nnz

    # ── Step 5: Intra-wave NNZ sort (descending, balances warp load) ──
    nnz_ordered = torch.gather(nnz_pad, 1, spectral_order_pad)  # NNZ in spectral order
    nnz_waves = nnz_ordered.view(H, n_waves, wave_size)  # (H, n_waves, wave_size)
    wave_mean_nnz = nnz_waves.float().mean(dim=2)  # (H, n_waves)

    # ── Step 6: Inter-wave schedule (dense/loaded waves first → latency hiding) ──
    wave_order = wave_mean_nnz.argsort(dim=1, descending=True)  # (H, n_waves)

    # ── Step 7: Intra-wave sort by NNZ (descending, balances warp divergence) ──
    within_wave_order = nnz_waves.argsort(dim=2, descending=True)  # (H, n_waves, wave_size)

    # ── Step 8: Apply intra-wave sort, then inter-wave reorder ──
    spectral_waves = spectral_order_pad.view(H, n_waves, wave_size)
    spectral_sorted = torch.gather(spectral_waves, 2, within_wave_order)

    wave_order_exp = wave_order.unsqueeze(2).expand(H, n_waves, wave_size)
    result_padded = torch.gather(spectral_sorted, 1, wave_order_exp)

    # ── Step 9: Strip padding ──
    valid_mask = result_padded < MB
    result = result_padded[valid_mask].view(H, MB).contiguous()

    # Reshape back to original leading dims
    if leading:
        result = result.reshape(*leading, MB)
    return result


def fiedler_local_reorder(mask_float, wave_size=132, macro_waves=1, n_iter=20):
    """Fiedler reorder with macro-block locality preservation (fiedler_local_nnz).

    Preserves Fiedler structural ordering at macro-block granularity, then
    repacks rows by NNZ within each macro-block so consecutive wave_size
    chunks become NNZ-homogeneous without destroying global ordering.

    Args:
        mask_float: (..., MB, NB) float
        wave_size: rows per wave (default 132)
        macro_waves: waves per macro block (default 1)
        n_iter: power iterations (default 20)
    Returns:
        perm: (..., MB) int64
    """
    *leading, MB, NB = mask_float.shape
    H = 1 if not leading else math.prod(leading)
    mask = mask_float.reshape(H, MB, NB)
    device = mask.device
    macro_waves = max(1, int(macro_waves))
    macro_size = wave_size * macro_waves
    n_macros = (MB + macro_size - 1) // macro_size
    total = n_macros * macro_size
    pad = total - MB
    n_waves = total // wave_size

    nnz = mask.sum(dim=2)
    Mt = mask.transpose(1, 2)

    # Degree and normalized Laplacian
    ones = torch.ones(H, MB, 1, device=device)
    deg = torch.bmm(mask, torch.bmm(Mt, ones)).squeeze(2)
    dinv = deg.clamp(min=1e-8).rsqrt()

    # Correct trivial eigenvector: sqrt(deg) for normalized adjacency
    trivial = deg.clamp(min=0).sqrt().unsqueeze(2)
    trivial_norm = trivial.norm(dim=1, keepdim=True)
    trivial = torch.where(trivial_norm > 1e-8,
                          trivial / trivial_norm.clamp(min=1e-8),
                          torch.ones(H, MB, 1, device=device) / (MB ** 0.5))

    gen = torch.Generator(device=device).manual_seed(42)
    v = torch.randn(H, MB, 1, device=device, generator=gen)
    v = v - torch.bmm(trivial.transpose(1, 2), v) * trivial
    v = v / v.norm(dim=1, keepdim=True).clamp(min=1e-8)

    for _ in range(n_iter):
        x = dinv.unsqueeze(2) * v
        y = torch.bmm(mask, torch.bmm(Mt, x))
        v = dinv.unsqueeze(2) * y
        v = v - torch.bmm(trivial.transpose(1, 2), v) * trivial
        v = v / v.norm(dim=1, keepdim=True).clamp(min=1e-8)

    spectral_order = v[:, :, 0].argsort(dim=1)  # (H, MB)

    # Pad
    if pad > 0:
        pad_idx = torch.arange(MB, MB + pad, device=device).unsqueeze(0).expand(H, -1)
        order_pad = torch.cat([spectral_order, pad_idx], dim=1)
        nnz_full = torch.cat([nnz, torch.zeros(H, pad, dtype=nnz.dtype, device=device)], dim=1)
        nnz_sort = torch.cat([nnz, torch.full((H, pad), -1e30, dtype=nnz.dtype, device=device)], dim=1)
    else:
        order_pad = spectral_order
        nnz_full = nnz
        nnz_sort = nnz

    # Preserve spectral locality at macro granularity, repack by NNZ inside each macro
    macro_rows = order_pad.view(H, n_macros, macro_size)
    macro_nnz = torch.gather(nnz_sort, 1, order_pad).view(H, n_macros, macro_size)
    macro_nnz_order = macro_nnz.argsort(dim=2, descending=True)
    macro_rows = torch.gather(macro_rows, 2, macro_nnz_order)

    wave_rows = macro_rows.view(H, n_waves, wave_size)
    wave_nnz = torch.gather(nnz_full, 1, macro_rows.view(H, total)).view(H, n_waves, wave_size)

    # Dense waves first, NNZ descending within each wave
    within = wave_nnz.argsort(dim=2, descending=True)
    wave_rows = torch.gather(wave_rows, 2, within)
    wave_nnz = torch.gather(wave_nnz, 2, within)

    wave_mean = wave_nnz.float().mean(dim=2)
    wave_order = wave_mean.argsort(dim=1, descending=True)
    wave_order_exp = wave_order.unsqueeze(2).expand(H, n_waves, wave_size)
    result_padded = torch.gather(wave_rows, 1, wave_order_exp)

    valid = result_padded < MB
    result = result_padded[valid].view(H, MB).contiguous()

    if leading:
        result = result.reshape(*leading, MB)
    return result


def lexicographical_reorder(mask_float):
    """Sort blocks by NNZ pattern lexicographically (column-major).
    Simple, O(MB*log(MB)*NB) — good for low-density masks with similar NNZ patterns.

    Reference: flash_attn.py:511
    """
    *leading, MB, NB = mask_float.shape
    H = 1 if not leading else math.prod(leading)
    mask = mask_float.reshape(H, MB, NB)
    device = mask.device

    perm_list = []
    for h in range(H):
        nnz_patterns = mask[h]  # (MB, NB)
        # Build sort key: majority of columns first, then subordinate columns
        col_bits = [nnz_patterns[:, j].int() * (2 ** min(j, 62))
                    for j in range(min(NB, 63))]
        key = sum(col_bits)
        perm_h = torch.argsort(key, descending=True)
        perm_list.append(perm_h)

    perm = torch.stack(perm_list)  # (H, MB)
    if leading:
        perm = perm.reshape(*leading, MB)
    return perm


def sorted_kv_reorder(mask_float, perm, wave_size=132, order="desc"):
    """Apply KV column rearrangement to the reordered mask.

    After row reorder, columns within each wave are rearranged to maximize
    spatial locality. Supports 'asc', 'desc', 'snake' (alternating per wave).

    Reference: flash_attn.py:474 (_apply_kv_order)

    Args:
        mask_float: (..., MB, NB) original block mask (before row reorder)
        perm: (..., MB) row permutation
        wave_size: int
        order: 'asc' | 'desc' | 'snake' | 'snake_inv'

    Returns:
        reordered_col_indices: (..., MB, NB) int32 column indices per block row
        reordered_col_counts: (..., MB) int32 valid column count per block row
    """
    *leading, MB, NB = mask_float.shape
    H = 1 if not leading else math.prod(leading)
    mask = mask_float.reshape(H, MB, NB)
    device = mask.device

    # Apply row perm to get reordered mask
    perm_exp = perm.unsqueeze(-1).expand_as(mask)
    reordered_mask = torch.gather(mask, 1 - H, perm_exp)  # gather along MB dim

    cnt_all = reordered_mask.sum(dim=-1, dtype=torch.int32)  # (H, MB)
    # Sort columns: valid cols first (ascending order by default)
    sorted_cols = torch.argsort(~reordered_mask.int(), dim=-1, stable=True).int()  # (H, MB, NB)

    if order == "asc":
        out = sorted_cols
    else:
        col_range = torch.arange(NB, device=device).view(1, 1, NB)
        valid = col_range < cnt_all.unsqueeze(-1)
        # Descending: reverse the valid columns within each row
        src = torch.where(
            valid,
            (cnt_all.unsqueeze(-1) - 1 - col_range).clamp(min=0),
            col_range,
        )
        desc_cols = torch.gather(sorted_cols, 2, src.long())

        if order in ("snake", "snake_inv"):
            wave_id = torch.arange(MB, device=device).view(1, MB, 1) // wave_size
            flip = (wave_id % 2 == 1)
            if order == "snake_inv":
                flip = ~flip
            out = torch.where(flip, desc_cols, sorted_cols)
        else:
            out = desc_cols

    out = out * (col_range < cnt_all.unsqueeze(-1)).int()

    if leading:
        out = out.reshape(*leading, MB, NB)
        cnt_all = cnt_all.reshape(*leading, MB)
    return out, cnt_all


def adaptive_spectral_reorder(mask_float, wave_size=132, n_iter=20,
                               min_gain=0.02, reuse_iters=0):
    """Feature-driven adaptive algorithm selector (greedy_reorder_cuda.py:5250).

    Uses static features (density, row/col CV) to pick the best reorder:
      - row_cv < 0.03 and col_cv < 0.03 → identity (uniform masks)
      - density < 0.02 → identity
      - density > 0.97 → identity
      - density < 0.32 → fiedler_wave or wave_overlap
      - otherwise → fiedler variants

    Returns identity permutation when expected gain below threshold.

    Args:
        mask_float: (..., MB, NB) float
        wave_size: int
        n_iter: int
        min_gain: skip reorder if expected DRAM gain below this
        reuse_iters: number of times the reorder will be reused
    Returns:
        perm: (..., MB) int64
        selected: str — algorithm name used
    """
    *leading, MB, NB = mask_float.shape
    H = 1 if not leading else math.prod(leading)
    mask = mask_float.reshape(H, MB, NB)
    device = mask.device

    density = mask.float().mean().item()
    nnz = mask.sum(dim=2).float()
    avg_nnz = nnz.mean().item()
    row_mean = nnz.mean(dim=1)
    row_cv = (nnz.std(dim=1, unbiased=False) / row_mean.clamp(min=1.0)).mean().item()
    col_nnz = mask.sum(dim=1).float()
    col_mean = col_nnz.mean(dim=1)
    col_cv = (col_nnz.std(dim=1, unbiased=False) / col_mean.clamp(min=1.0)).mean().item()

    identity_perm = torch.arange(MB, device=device).unsqueeze(0).expand(H, -1)

    # Quick exits
    if MB < wave_size * 2 or density > 0.97 or density < 0.02:
        return identity_perm, "identity"
    if row_cv < 0.03 and col_cv < 0.03:
        return identity_perm, "identity"

    # Density-driven algorithm selection (from NCU sweep data)
    if density < 0.32:
        selected = "fiedler"  # structural locality
    elif density < 0.42:
        selected = "fiedler_local" if MB >= 250 else "fiedler"
    elif density < 0.53:
        selected = "fiedler_local" if MB < 200 else "fiedler"
    elif density < 0.62:
        selected = "fiedler" if row_cv > 0.10 else "fiedler"
    elif density < 0.70:
        selected = "fiedler" if row_cv > 0.047 else ("fiedler" if row_cv < 0.035 else "fiedler")
    else:
        selected = "lexicographical"

    # Dispatch
    if selected == "fiedler":
        perm = fiedler_reorder(mask_float, wave_size=wave_size, n_iter=n_iter)
    elif selected == "fiedler_local":
        perm = fiedler_local_reorder(mask_float, wave_size=wave_size, n_iter=n_iter)
    elif selected == "lexicographical":
        perm = lexicographical_reorder(mask_float)
    else:
        perm = identity_perm

    if leading:
        perm = perm.reshape(*leading, MB)
    return perm, selected


@dataclass
class ReorderInfo:
    """Result of a block reorder operation."""
    perm: torch.Tensor                    # (1, MB) row permutation: reordered_row = perm[0, orig_row]
    kv_indices: torch.Tensor              # reordered kv_indices
    kv_num_blocks: torch.Tensor           # reordered kv_num_blocks
    inv_perm: Optional[torch.Tensor] = None  # inverse: orig_row = inv_perm[0, reordered_row]
    full_kv_indices: Optional[torch.Tensor] = None
    full_kv_num_blocks: Optional[torch.Tensor] = None
    query: Optional[torch.Tensor] = None  # reordered query (None if no Q reorder)
    baseline_hit_rate: float = 0.0
    reordered_hit_rate: float = 0.0
    reorder_mode: str = "wave_overlap"


def make_reordered_score_mod(original_score_mod, inv_perm, block_size):
    """Create a score_mod wrapper that maps reordered Q positions to original Q positions.

    Uses torch.where chains to avoid // and % operations that bishengir
    (NPU compiler) cannot lower.

    Args:
        original_score_mod: callable(score, b, h, q_idx, kv_idx) -> score
        inv_perm: 1D tensor/list where inv_perm[j] = original block for reordered block j
        block_size: int — logical Q block size

    Returns:
        reordered_score_mod with same signature
    """
    n_blocks = len(inv_perm)
    inv_list = [int(inv_perm[i]) for i in range(n_blocks)]

    def reordered_score_mod(score, b, h, q_idx, kv_idx):
        orig_q = q_idx  # default: identity (for out-of-range positions)

        for i in range(n_blocks):
            block_start = i * block_size
            block_end = (i + 1) * block_size
            in_block = (q_idx >= block_start) & (q_idx < block_end)
            orig_pos = inv_list[i] * block_size + (q_idx - block_start)
            orig_q = torch.where(in_block, orig_pos, orig_q)

        return original_score_mod(score, b, h, orig_q, kv_idx)

    return reordered_score_mod


def reorder_flex_forward(
    q: torch.Tensor, k: torch.Tensor, v: torch.Tensor,
    kv_num_blocks: torch.Tensor, kv_indices: torch.Tensor,
    full_kv_num_blocks: Optional[torch.Tensor], full_kv_indices: Optional[torch.Tensor],
    BLOCK_SIZE_M: int, BLOCK_SIZE_N: int,
    mode: str = "wave_overlap",
    wave_size: int = 132,
    sorted_kv: bool = True,
    verbose: bool = False,
) -> Tuple[ReorderInfo, float, float]:
    """Apply block reorder to flex attention inputs.

    This function takes the existing block mask, runs the selected reorder
    algorithm, and returns reordered indices + query.

    Args:
        q, k, v: QKV tensors
        kv_num_blocks, kv_indices: original block mask sparse data
        full_kv_num_blocks, full_kv_indices: original block mask full-block data (optional)
        BLOCK_SIZE_M, BLOCK_SIZE_N: logical block sizes from BlockMask
        mode: reorder algorithm name (default "wave_overlap")
        wave_size: wave partition size for reorder
        sorted_kv: whether to sort KV indices within each row
        verbose: print debug info

    Returns:
        tuple: (ReorderInfo, baseline_hit_rate, reordered_hit_rate)
    """
    B, H_q, seq_len_q, head_dim = q.shape
    _, H_kv, seq_len_kv, _ = k.shape

    n_blocks_q = (seq_len_q + BLOCK_SIZE_M - 1) // BLOCK_SIZE_M
    n_blocks_kv = (seq_len_kv + BLOCK_SIZE_N - 1) // BLOCK_SIZE_N

    # Compute baseline hit rate (CPU for Python loops)
    baseline_hit = compute_block_hit_rate(
        kv_indices.cpu(), kv_num_blocks.cpu(),
        full_kv_indices.cpu() if full_kv_indices is not None else None,
        full_kv_num_blocks.cpu() if full_kv_num_blocks is not None else None,
    )
    if verbose:
        print(f"[reorder] Baseline hit rate: {baseline_hit:.4f}")

    # Build dense mask from kv_indices + full_kv_indices, run reorder on CPU
    n_blocks = min(n_blocks_q, kv_indices.shape[2])
    mask_float = rebuild_block_mask(
        kv_num_blocks.cpu(), kv_indices.cpu(),
        n_blocks, n_blocks_kv,
        full_kv_num_blocks=full_kv_num_blocks.cpu() if full_kv_num_blocks is not None else None,
        full_kv_indices=full_kv_indices.cpu() if full_kv_indices is not None else None,
        device="cpu",
    )

    if verbose:
        print(f"[reorder] Dense mask ({n_blocks}x{n_blocks_kv}):")
        print(mask_float)

    # Run reorder algorithm on CPU
    if mode == "wave_overlap":
        perm = wave_overlap_reorder(mask_float, wave_size=wave_size)
    elif callable(mode):
        perm = mode(mask_float, wave_size=wave_size)
    else:
        raise ValueError(f"Unknown reorder mode: {mode}")

    # NOTE: perm from wave_overlap_reorder has shape (B, MB) or (1, MB).
    # perm[0, i] = original row index to place at reordered position i.
    # That is: reordered_mask[row] = original_mask[perm[0, row]]
    # And:     reordered_Q[row] = original_Q[perm[0, row]]

    # Reorder kv_indices and kv_num_blocks rows by perm
    reordered_kv_indices = torch.zeros_like(kv_indices)
    reordered_kv_num_blocks = torch.zeros_like(kv_num_blocks)
    reordered_full_kv_indices = None
    reordered_full_kv_num_blocks = None

    for row in range(n_blocks):
        src_row = perm[0, row].item()
        reordered_kv_num_blocks[..., row] = kv_num_blocks[..., src_row]
        reordered_kv_indices[..., row, :] = kv_indices[..., src_row, :]

    # Reorder full blocks if present
    if full_kv_num_blocks is not None and full_kv_indices is not None:
        reordered_full_kv_num_blocks = torch.zeros_like(full_kv_num_blocks)
        reordered_full_kv_indices = torch.zeros_like(full_kv_indices)
        n_full_rows = min(full_kv_num_blocks.shape[2], perm.shape[1])
        for row in range(n_full_rows):
            src_row = perm[0, row].item()
            reordered_full_kv_num_blocks[..., row] = full_kv_num_blocks[..., src_row]
            reordered_full_kv_indices[..., row, :] = full_kv_indices[..., src_row, :]

    # Reorder Q along the sequence (block) dimension
    # q_blocks shape: [B, H, n_blocks_q, BLOCK_SIZE_M, head_dim]
    q_blocks = q.reshape(B, H_q, n_blocks_q, BLOCK_SIZE_M, head_dim)
    perm_expanded = perm[0, :n_blocks_q].long()
    reordered_q_blocks = q_blocks[:, :, perm_expanded]
    reordered_q = reordered_q_blocks.reshape(B, H_q, n_blocks_q * BLOCK_SIZE_M, head_dim)
    reordered_q = reordered_q[:, :, :seq_len_q, :].contiguous()

    # Compute reordered hit rate
    reordered_hit = compute_block_hit_rate(
        reordered_kv_indices, reordered_kv_num_blocks,
        reordered_full_kv_indices, reordered_full_kv_num_blocks,
    )
    if verbose:
        print(f"[reorder] Reordered hit rate: {reordered_hit:.4f} "
              f"(delta: {reordered_hit - baseline_hit:+.4f})")

    # Compute inverse permutation for un-permuting output
    # perm[0, i] = original_row at reordered position i
    # inv_perm[0, orig_row] = reordered position
    inv_perm = torch.argsort(perm, dim=1)  # (1, MB)

    return ReorderInfo(
        perm=perm,
        kv_indices=reordered_kv_indices,
        kv_num_blocks=reordered_kv_num_blocks,
        inv_perm=inv_perm,
        full_kv_indices=reordered_full_kv_indices,
        full_kv_num_blocks=reordered_full_kv_num_blocks,
        query=reordered_q,
        baseline_hit_rate=baseline_hit,
        reordered_hit_rate=reordered_hit,
        reorder_mode=mode,
    ), baseline_hit, reordered_hit


def unpermute_output(output: torch.Tensor, inv_perm: torch.Tensor,
                     BLOCK_SIZE_M: int, seq_len_q: int) -> torch.Tensor:
    """Restore output tensor to original row order after reordered flex_attention.

    Args:
        output: Tensor[B, H, seq_len_q_reordered, D] — flex_attention output on reordered Q
        inv_perm: Tensor[1, n_blocks_q] — inverse permutation (orig_row = inv_perm[0, reordered_row])
        BLOCK_SIZE_M: int — Q block size
        seq_len_q: int — original (pre-reorder) sequence length

    Returns:
        Tensor[B, H, seq_len_q, D] — output in original row order
    """
    B, H, _, D = output.shape
    n_blocks_q = (seq_len_q + BLOCK_SIZE_M - 1) // BLOCK_SIZE_M

    # Reshape into blocks
    out_blocks = output.reshape(B, H, n_blocks_q, BLOCK_SIZE_M, D)

    # Apply inverse permutation: unpermuted[orig_row] = out_blocks[reordered_row]
    # inv_perm[0, reordered_row] = orig_row
    # So out_blocks[:, :, inv_perm[0]] puts output at reordered_row into orig_row position
    inv = inv_perm[0, :n_blocks_q].to(output.device)
    unpermuted_blocks = out_blocks[:, :, inv]

    # Reshape back and trim to original seq_len
    unpermuted = unpermuted_blocks.reshape(B, H, n_blocks_q * BLOCK_SIZE_M, D)
    return unpermuted[:, :, :seq_len_q, :]


REORDER_REGISTRY = {
    "wave_overlap": wave_overlap_reorder,
    "fiedler": fiedler_reorder,
    "fiedler_local": fiedler_local_reorder,
    "lexicographical": lexicographical_reorder,
    "adaptive": adaptive_spectral_reorder,
}
